package gis

import("sort";"strings";"time")
type DiscoveryRecord struct{AssetID string `json:"asset_id"`;Kind string `json:"kind"`;Name string `json:"name"`;Status string `json:"status"`;ObservedAt time.Time `json:"observed_at"`}
type Drift struct{AssetID string `json:"asset_id"`;Kind string `json:"kind"`;Expected string `json:"expected"`;Observed string `json:"observed"`;Severity string `json:"severity"`}
type Reconciler struct{}
func NewReconciler()*Reconciler{return &Reconciler{}}
func(r *Reconciler)Compare(expected []FiberAsset,observed []DiscoveryRecord)[]Drift{observedByID:=make(map[string]DiscoveryRecord,len(observed));for _,v:=range observed{id:=strings.TrimSpace(v.AssetID);if id!=""{v.AssetID=id;v.Kind=strings.TrimSpace(v.Kind);v.Status=strings.TrimSpace(v.Status);observedByID[id]=v}};out:=make([]Drift,0);for _,e:=range expected{id:=strings.TrimSpace(e.ID);if id==""{continue};o,ok:=observedByID[id];kind:=strings.TrimSpace(string(e.Type));expectedStatus:=strings.TrimSpace(e.Status);if !ok{out=append(out,Drift{AssetID:id,Kind:kind,Expected:expectedStatus,Observed:"missing",Severity:"high"});continue};if expectedStatus!=""&&o.Status!=""&&expectedStatus!=o.Status{out=append(out,Drift{AssetID:id,Kind:kind,Expected:expectedStatus,Observed:o.Status,Severity:"medium"})}};sort.SliceStable(out,func(i,j int)bool{rank:=func(s string)int{switch strings.ToLower(s){case "high":return 0;case "medium":return 1;case "low":return 2;default:return 3}};ri,rj:=rank(out[i].Severity),rank(out[j].Severity);if ri!=rj{return ri<rj};if out[i].AssetID!=out[j].AssetID{return out[i].AssetID<out[j].AssetID};return out[i].Kind<out[j].Kind});return out}
